    map.createPane('pane_MPA');
    map.getPane('pane_MPA').style.zIndex = 397;
    function mpaStyle(f) {
        var p = f.properties;
        if (p.mobile_ban) {
            return {color: '#01665E', weight: 1.4, dashArray: p.exemption ? '5 3' : '', fillColor: '#01665E', fillOpacity: 0.3};
        }
        return {color: '#35978F', weight: 1, dashArray: '2 3', fillColor: '#80CDC1', fillOpacity: 0.2};
    }
    function mpaLayer(data, label) {
        return L.geoJson(data, {
            pane: 'pane_MPA',
            style: mpaStyle,
            onEachFeature: function (f, layer) {
                var p = f.properties;
                var html = '<b>' + esc(p.name) + '</b><br><i>Proposed measures, ' + label + ' (2026 consultation)</i>' +
                    '<p style="margin:6px 0"><b>' + (p.mobile_ban ? 'Bottom trawls and dredges banned' : 'Other gear restrictions only') + '</b><br>' +
                    'Gear restricted: ' + esc(p.gear) + '</p>' +
                    (p.exemption ? '<p style="margin:6px 0"><b>Exemption:</b> ' + esc(p.exemption) + '</p>' : '') +
                    (p.type && p.type !== 'Full Year' ? '<p style="margin:6px 0"><b>Timing:</b> ' + esc(p.type) + '</p>' : '') +
                    '<p style="margin:6px 0">' + esc(p.rule) + '</p>' +
                    '<small>Source: Scottish Government MPA/PMF consultation 2026 (NMPi). Proposals, not current rules.</small>';
                layer.bindPopup(html, {maxHeight: 300, maxWidth: 320});
            }
        });
    }
    var mpaOpt1 = mpaLayer(json_MPA_Opt1, 'Option 1');
    var mpaOpt2 = mpaLayer(json_MPA_Opt2, 'Option 2');
    function mpaLegend(title) {
        return title + '<br /><table>' +
            '<tr><td><span style="display:inline-block;width:14px;height:12px;background:rgba(1,102,94,0.3);border:1.5px solid #01665E;"></span></td><td>Bottom trawls and dredges banned</td></tr>' +
            '<tr><td><span style="display:inline-block;width:14px;height:12px;background:rgba(128,205,193,0.2);border:1px dotted #35978F;"></span></td><td>Other gear restrictions only</td></tr>' +
            '</table>';
    }

    // --- Add both to the layer list ---
    overlaysTree.unshift(
        {label: '<span style="display:inline-block;width:10px;height:10px;margin:0 4px;transform:rotate(45deg);background:#C2185B;border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,0.3);vertical-align:middle;"></span> Seagrass restoration sites', layer: restoration}
    );
    overlaysTree.push(
        {label: '<span style="display:inline-block;width:22px;border-top:2px dashed #08306B;vertical-align:middle;"></span> 6 nautical mile limit', layer: sixnm},
        {label: 'No-trawl and no-dredge zones<br /><table>' +
            '<tr><td><span style="display:inline-block;width:14px;height:12px;background:rgba(241,163,64,0.4);border:1px solid #B35806;"></span></td><td>Conservation areas</td></tr>' +
            '<tr><td><span style="display:inline-block;width:14px;height:12px;background:rgba(158,158,158,0.25);border:1px dashed #6B6B6B;"></span></td><td>Other closures (military, health hazard)</td></tr>' +
            '</table>', layer: trawl}
    );
    // Scotland outline layer removed (land comes from the grey basemap instead)
    if (typeof layer_Scotland_outline_0 !== 'undefined') {
        overlaysTree = overlaysTree.filter(function (e) { return e.layer !== layer_Scotland_outline_0; });
        lay.setOverlayTree(overlaysTree);
        map.removeLayer(layer_Scotland_outline_0);
    }
    // MPA measures go straight after the PMF options in the list (unticked by default)
    (function () {
        var entries = [
            {label: mpaLegend('Proposed MPA measures &ndash; Option 1'), layer: mpaOpt1},
            {label: mpaLegend('Proposed MPA measures &ndash; Option 2'), layer: mpaOpt2}
        ];
        var i = -1;
        for (var k = 0; k < overlaysTree.length; k++) {
            if (typeof layer_PMFOption2_1 !== 'undefined' && overlaysTree[k].layer === layer_PMFOption2_1) { i = k; }
        }
        if (i >= 0) { overlaysTree.splice.apply(overlaysTree, [i + 1, 0].concat(entries)); }
        else { overlaysTree.push.apply(overlaysTree, entries); }
    })();
    lay.setOverlayTree(overlaysTree);

    map.attributionControl.addAttribution('Proposed MPA measures: Scottish Government (NMPi, OGL); Restoration sites: SeagrassRestorer (Project Seagrass); Fishing restrictions: Scottish Government &copy; Crown copyright; 6 nm limit: Admiralty Maritime Data Solutions');

    // --- "Point in time" note in the info box ---
    var abs = document.getElementById('abstract');
    if (abs) {
        abs.innerHTML = '<b>Map for the 2026 MPA and PMF consultation</b><br>' +
            'A snapshot: data correct as of October 2026 and not updated live. ' +
            'Proposed measures and management areas are consultation proposals, not current rules.';
        abs.style.maxWidth = '280px';
    }
